/*
 * A315762  Coordination sequence Gal.6.627.5 where Gal.u.t.v denotes the
 *          coordination sequence for a vertex of type v in tiling number t in
 *          the Galebach list of u-uniform tilings.
 * https://oeis.org/A315762
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 6*n - k(n) where k(n) counts the number of indices ≤ n at
 *            which the incremental difference a(n) - a(n-1) equals 5. The
 *            indices form the sequence 5, 7, 16, 18, 27, 29, …, which is
 *            generated by starting at 5 and repeatedly adding 2, 9, 2, 9, 2,
 *            9, …
 * Range:     u8 n <= 43, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n) {
    if (n == 0) {
        return (seq_t)1;
    }

    /* Base linear term */
    seq_t res = (seq_t)6 * (seq_t)n;

    /* Count how many “5‑step” indices are ≤ n */
    size_t count = 0;
    if (n >= 5) {
        idx_t g = 5;        /* first 5‑step index */
        count = 1;
        int add_two = 1;    /* next increment is +2 */

        for (;;) {
            if (add_two)
                g += 2;
            else
                g += 9;

            if (g > n)
                break;

            count++;
            add_two ^= 1;    /* toggle between +2 and +9 */
        }
    }

    return res - (seq_t)count;
}
